package webapp

const pageHTML = `<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Runtime Security Console</title>
<style>
:root{font:14px system-ui,Segoe UI,sans-serif;background:#0b1220;color:#e2edf8}*{box-sizing:border-box}body{margin:0}header{padding:18px 3%;background:#111d30;border-bottom:1px solid #284057;display:flex;justify-content:space-between;align-items:center}h1{font-size:21px;margin:0}h2{font-size:18px}h3{font-size:15px}a{color:#7fd6e8}main{padding:20px 2.5%;max-width:1800px;margin:auto}nav{display:flex;gap:8px;margin-bottom:18px}button,.action{background:#1c344e;border:1px solid #385770;color:#e9f7ff;border-radius:7px;padding:9px 11px;cursor:pointer;text-decoration:none;display:inline-block}button:hover,.action:hover{background:#305375}button.active{background:#12738d}button:disabled{opacity:.5;cursor:not-allowed}input,select,textarea{background:#13283e;border:1px solid #355269;color:white;border-radius:7px;padding:10px;width:100%;font:inherit}label{display:block;margin:9px 0 4px;color:#bfd2e2}textarea{min-height:70px}.toolbar{display:grid;grid-template-columns:minmax(140px,2fr) minmax(100px,1fr) auto;gap:10px;margin-bottom:14px}.workspace.single-view{display:block}.workspace.single-view>section{width:100%}.exceptions-toolbar{display:grid;grid-template-columns:minmax(220px,2fr) minmax(160px,1fr) auto;gap:12px;align-items:end;padding:16px}.exceptions-toolbar label{margin:0}.workspace{display:grid;grid-template-columns:minmax(360px,1.3fr) minmax(390px,1fr);gap:16px;align-items:start}.panel{background:#122136;border:1px solid #2b4159;border-radius:10px;min-width:0;overflow:hidden}.panel-inner{padding:16px}.detail-pane{position:sticky;top:12px;max-height:calc(100vh - 26px);overflow:auto}.muted{color:#9eb4cb;font-size:12px}.error{color:#ff9ea4}.pill{padding:3px 8px;border-radius:12px;background:#2a3c50;display:inline-block}.critical{color:#ff8c95}.high{color:#ffbf80}.medium{color:#f0d88f}.table-scroll{overflow-x:auto;max-height:75vh;overflow-y:auto}table{width:100%;border-collapse:collapse;font-size:12px}th,td{padding:12px 10px;text-align:left;border-bottom:1px solid #273c50;white-space:nowrap}th{background:#172a40;position:sticky;top:0;cursor:pointer;color:#c4deef;user-select:none}th:hover{background:#294763}tr[data-id]{cursor:pointer}tbody tr:hover,tbody tr.selected{background:#26435a}.card{background:#182d44;border:1px solid #354e65;border-radius:8px;padding:13px;margin:10px 0;overflow-wrap:anywhere}pre{background:#091828;padding:12px;border-radius:7px;font-size:12px;white-space:pre-wrap;word-break:break-all;max-height:400px;overflow:auto}.event{border-left:3px solid #3bacc1}.row{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.keyval{display:grid;grid-template-columns:125px minmax(0,1fr);gap:8px;margin:7px 0;word-break:break-word}.empty{padding:30px;text-align:center;color:#aabfd3}.detail-page{max-width:1100px;margin:auto}.field-picker{display:grid;grid-template-columns:1fr;gap:6px}.field-picker button{text-align:left;font-size:12px;white-space:normal;overflow-wrap:anywhere}.field-picker button strong{display:block;color:#83cfe2}.notice{border-left:3px solid #efb66d;padding:9px;background:#283244;margin:12px 0}.hidden{display:none!important}@media(max-width:1050px){.workspace{grid-template-columns:1fr}.detail-pane{position:static;max-height:none}}@media(max-width:560px){.exceptions-toolbar{grid-template-columns:1fr}.toolbar{grid-template-columns:1fr}header{align-items:start;gap:8px}table{font-size:11px}.keyval{grid-template-columns:90px 1fr}}
.metric-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px;padding:16px}.metric-tile{background:#182d44;border:1px solid #354e65;border-radius:8px;padding:15px}.metric-value{font-size:25px;font-weight:700;margin-top:8px}.metric-charts{display:grid;grid-template-columns:repeat(auto-fit,minmax(310px,1fr));gap:12px;padding:0 16px 16px}.metric-chart{background:#182d44;border:1px solid #354e65;border-radius:8px;padding:12px}.metric-chart svg{display:block;width:100%;height:120px}.metric-status{padding:14px 16px}.metric-chart h3{margin:0 0 8px}</style></head><body>
<header><h1>RED-O</h1><span class="muted">Tetragon · ClickHouse · Go</span></header>
<main><nav><button id="nav-alerts" data-tab="alerts">Alerts</button><button id="nav-events" data-tab="events">Events</button><button id="nav-exceptions" data-tab="exceptions">Exceptions</button><button id="nav-agents" data-tab="agents">Agents</button><button id="nav-metrics" data-tab="metrics">Metrics</button></nav>
<div id="search-tools" class="toolbar"><input id="query" placeholder="Поиск по Pod, процессу, IP, пути, правилу или JSON"><input id="namespace" placeholder="Namespace"><button id="search-btn">Найти</button></div>
<div id="workspace" class="workspace"><section class="panel"><div class="panel-inner row"><h2 id="list-title">Предупреждения</h2><span class="muted" id="sort-description"></span></div><div id="list" class="table-scroll"></div></section><aside id="detail" class="panel detail-pane"><div class="empty">Выберите запись слева для расследования</div></aside></div>
</main>
<script>
'use strict';
const $=id=>document.getElementById(id);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pathId=location.pathname.startsWith('/alert/')?decodeURIComponent(location.pathname.slice(7)):'';
const newExceptionPage=location.pathname==='/exception/new';
let tab='alerts',items=[],sort='timestamp',direction='desc',activeId='',detailsData=null;
let exceptionRuleFilter='',exceptionSearch='';
const fields={alerts:[['timestamp','Время'],['rule_id','Правило'],['severity','Severity'],['namespace','Namespace'],['pod','Pod']],events:[['timestamp','Время'],['event_type','Тип'],['process','Процесс'],['namespace','Namespace'],['pod','Pod'],['file_path','Путь'],['destination_ip','IP']]};
async function api(url,opt){const r=await fetch(url,opt);if(!r.ok)throw new Error((await r.text()).slice(0,300));return r.json()}
const val=(a,key)=>({timestamp:a.timestamp,rule_id:a.rule_id,severity:a.severity,namespace:a.kubernetes?.namespace,pod:a.kubernetes?.pod,event_type:a.event_type,process:a.process?.binary,file_path:a.file?.path,destination_ip:a.network?.destination_ip})[key]||'';
function setTab(name){
 tab=name;sort='timestamp';direction='desc';activeId='';detailsData=null;
 for(const b of document.querySelectorAll('nav button'))b.classList.toggle('active',b.dataset.tab===name);
 const noEventSearch=name==='exceptions'||name==='agents'||name==='metrics';
 $('search-tools').classList.toggle('hidden',noEventSearch);
 $('workspace').classList.toggle('single-view',noEventSearch);
 $('detail').classList.toggle('hidden',noEventSearch);
 if(!noEventSearch)$('detail').innerHTML='<div class="empty">Выберите запись слева для расследования</div>';
 $('list-title').textContent=name==='alerts'?'Предупреждения':name==='events'?'События':name==='agents'?'Наблюдаемые узлы':name==='metrics'?'Метрики детектора':'Исключения';
 load();
}
function header(){return '<thead><tr>'+fields[tab].map(([key,title])=>'<th data-sort="'+key+'" title="Сортировать">'+esc(title)+(sort===key?(direction==='asc'?' ↑':' ↓'):' ↕')+'</th>').join('')+'</tr></thead>'}
function renderTable(){let html='<table>'+header()+'<tbody>';for(const a of items){const id=tab==='alerts'?a.alert_id:a.event_id;html+='<tr data-id="'+esc(id)+'" class="'+(id===activeId?'selected':'')+'">'+fields[tab].map(([key])=>'<td>'+ (key==='severity'?'<span class="pill '+esc(a.severity)+'">'+esc(a.severity)+'</span>':esc(val(a,key)))+'</td>').join('')+'</tr>'}html+='</tbody></table>';if(!items.length)html='<div class="empty">Совпадений не найдено</div>';$('list').innerHTML=html;$('list').querySelectorAll('th').forEach(el=>el.addEventListener('click',()=>{const key=el.dataset.sort;direction=sort===key&&direction==='desc'?'asc':'desc';sort=key;load()}));$('list').querySelectorAll('tbody tr').forEach(el=>el.addEventListener('click',()=>select(el.dataset.id)));$('sort-description').textContent=items.length+' записей · '+sort+' '+direction}
async function load(){try{if(tab==='exceptions'){await loadExceptions();return}if(tab==='agents'){await loadAgents();return}if(tab==='metrics'){await loadMetrics();return}const q=new URLSearchParams({q:$('query').value,namespace:$('namespace').value,sort,dir:direction,limit:'500'});items=await api('/api/'+tab+'?'+q);renderTable()}catch(e){$('list').innerHTML='<div class="error panel-inner">'+esc(e.message)+'</div>'}}
async function select(id){activeId=id;renderTable();if(tab==='events'){const e=items.find(x=>x.event_id===id);$('detail').innerHTML='<div class="panel-inner"><h2>Событие</h2><pre>'+esc(JSON.stringify(e,null,2))+'</pre></div>';return}await showAlert(id)}
function fieldCandidates(event){const o=[['event_type',event.event_type],['process.binary',event.process?.binary],['process.uid',event.process?.uid],['file.path',event.file?.path],['network.destination_ip',event.network?.destination_ip],['network.destination_port',event.network?.destination_port],['kubernetes.pod',event.kubernetes?.pod],['kubernetes.container_id',event.kubernetes?.container_id]];return o.filter(([,v])=>v!==undefined&&v!==null&&v!=='')}
async function showAlert(id){try{detailsData=await api('/api/alerts/'+encodeURIComponent(id));const a=detailsData.alert,events=detailsData.events||[];let html='<div class="panel-inner"><div class="row"><h2>'+esc(a.rule_id)+' · '+esc(a.rule_name)+'</h2><span class="pill '+esc(a.severity)+'">'+esc(a.severity)+'</span></div><p>'+esc(a.description||'')+'</p><div class="card"><b>Почему создан Alert</b><p>'+esc(a.reason||'')+'</p><div class="keyval"><span class="muted">Namespace</span>'+esc(a.kubernetes?.namespace)+'</div><div class="keyval"><span class="muted">Pod</span>'+esc(a.kubernetes?.pod)+'</div><div class="keyval"><span class="muted">Время</span>'+esc(a.timestamp)+'</div><div class="keyval"><span class="muted">Alert UUID</span>'+esc(a.alert_id)+'</div></div><p><a class="action" href="/?tab=exceptions&rule='+encodeURIComponent(a.rule_id)+'">Исключения</a></p><h3>Связанные события ('+events.length+' из '+(a.related_event_ids||[]).length+')</h3>';
for(let i=0;i<events.length;i++){const e=events[i];html+='<div class="card event"><b>'+esc(e.event_type)+'</b> <span class="muted">'+esc(e.timestamp)+'</span><p>'+esc(e.process?.binary)+' · '+esc(e.file?.path||e.network?.destination_ip||'')+'</p><div class="muted">exec_id: '+esc(e.process?.exec_id)+'</div><details><summary>Исходный JSON</summary><pre>'+esc(JSON.stringify(e,null,2))+'</pre></details><details><summary>Создать исключение по полю этого события</summary><div class="field-picker">'+fieldCandidates(e).map(([field,v])=>'<a class="action" href="/exception/new?alert_id='+encodeURIComponent(a.alert_id)+'&event_id='+encodeURIComponent(e.event_id)+'&field='+encodeURIComponent(field)+'"><strong>'+esc(field)+'</strong> · '+esc(String(v))+' ↗</a>').join('')+'</div></details></div>'}
html+='</div>';$('detail').innerHTML=html;}catch(e){$('detail').innerHTML='<div class="panel-inner error">'+esc(e.message)+'</div>'}}
function exceptionForm(a,field,value){const expiry=new Date(Date.now()+7*86400000).toISOString().replace(/\.\d{3}Z$/,'Z');$('detail').insertAdjacentHTML('beforeend','<div class="panel-inner" id="exception-box"><h3>Исключение для '+esc(a.rule_id)+'</h3><div class="notice">Исключение применяется к будущим алертам. Выбранное поле должно совпасть хотя бы в одном связанном событии. Ограничение по Pod рекомендуется оставить включённым.</div><form id="exception-form"><label>Поле события</label><input value="'+esc(field)+'" readonly><label>Точное значение</label><input value="'+esc(value)+'" readonly><label>Namespace</label><input value="'+esc(a.kubernetes?.namespace)+'" readonly><label>Pod (можно очистить, расширив область исключения)</label><input name="pod" value="'+esc(a.kubernetes?.pod)+'"><label>Причина</label><textarea name="reason" required></textarea><label>Истекает (UTC, RFC3339)</label><input name="expires" value="'+esc(expiry)+'" required><p><button type="submit">Сохранить исключение</button> <button type="button" id="cancel-exception">Отмена</button></p><div id="exception-result"></div></form></div>');const pane=$('detail'),old=pane.querySelectorAll('#exception-box');for(let i=0;i<old.length-1;i++)old[i].remove();const form=$('exception-form');form.addEventListener('submit',async ev=>{ev.preventDefault();const payload={rule_id:a.rule_id,namespace:a.kubernetes.namespace,pod:form.elements.pod.value,field,value,reason:form.elements.reason.value,expires_at:form.elements.expires.value};try{await api('/api/exceptions?alert_id='+encodeURIComponent(a.alert_id),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});$('exception-result').textContent='Исключение сохранено. Для применения необходима настройка флага -exceptions в детекторе.'}catch(e){$('exception-result').textContent=e.message}});$('cancel-exception').addEventListener('click',()=>pane.querySelector('#exception-box').remove());pane.scrollTop=pane.scrollHeight}
async function loadExceptions(){
 const data=await api('/api/exceptions');
 const rule=exceptionRuleFilter.trim().toLowerCase(), q=exceptionSearch.trim().toLowerCase();
 const rules=[...new Set(data.map(e=>e.rule_id).filter(Boolean))].sort();
 const filtered=data.filter(e=>(!rule||String(e.rule_id).toLowerCase()===rule)&&(!q||[e.id,e.rule_id,e.namespace,e.pod,e.field,e.value,e.reason,e.expires_at].some(v=>String(v??'').toLowerCase().includes(q))));
 const toolbar='<div class="exceptions-toolbar"><label>Поиск исключений<input id="exceptions-query" placeholder="Правило, namespace, Pod, поле, значение, причина..." value="'+esc(exceptionSearch)+'"></label><label>Правило<select id="exceptions-rule"><option value="">Все правила</option>'+rules.map(x=>'<option value="'+esc(x)+'" '+(x===exceptionRuleFilter?'selected':'')+'>'+esc(x)+'</option>').join('')+'</select></label><button id="exceptions-clear">Сбросить</button></div>';
 $('list').innerHTML=toolbar+(filtered.map(e=>'<div class="card"><div class="row"><b>'+esc(e.rule_id)+'</b><span class="muted">'+esc(e.id)+'</span></div><p>'+esc(e.namespace)+' / '+esc(e.pod||'любой Pod')+'</p><p>'+esc(e.field||'без поля')+' = '+esc(e.value||'')+'</p><p>'+esc(e.reason)+'</p><span class="muted">До '+esc(e.expires_at)+'</span> <button data-remove="'+esc(e.id)+'">Удалить</button></div>').join('')||'<div class="empty">Совпадений не найдено</div>');
 $('exceptions-query').addEventListener('input',ev=>{exceptionSearch=ev.target.value;const selectionStart=ev.target.selectionStart;loadExceptions().then(()=>{const el=$('exceptions-query');el.focus();el.setSelectionRange(selectionStart,selectionStart)})});
 $('exceptions-rule').addEventListener('change',ev=>{exceptionRuleFilter=ev.target.value;loadExceptions()});
 $('exceptions-clear').addEventListener('click',()=>{exceptionRuleFilter='';exceptionSearch='';history.replaceState(null,'','/?tab=exceptions');loadExceptions()});
 $('list').querySelectorAll('[data-remove]').forEach(b=>b.addEventListener('click',async()=>{if(!confirm('Удалить исключение?'))return;try{await api('/api/exceptions/'+encodeURIComponent(b.dataset.remove),{method:'DELETE'});load()}catch(e){alert(e.message)}}));
 $('sort-description').textContent=filtered.length+' из '+data.length+' исключений';
}
async function loadAgents(){
 const result=await api('/api/agents');const data=result.agents||[];
 const badge=a=>a.status==='online'?'🟢 Online':a.status==='offline'?'🔴 Offline':a.status==='degraded'?'🟠 Degraded':a.status==='missing'?'🔴 Missing':'⚪ Unknown';
 $('list').innerHTML='<div class="notice">Live: Kubernetes API (Pod/Container/Node readiness). Collector: heartbeat каждые 5 секунд. Telemetry: ClickHouse (last observed event). Отсутствие событий не означает Offline. Проверка: '+esc(result.checked_at)+' <button id="refresh-agents">Обновить</button></div>'+(result.health_available?'':'<div class="error panel-inner">Kubernetes недоступен: '+esc(result.error)+'; отображается только сохранённая телеметрия.</div>')+'<table><thead><tr><th>Node</th><th>Agent Pod</th><th>Status</th><th>Node Ready</th><th>Pod Ready</th><th>Restarts</th><th>Collector</th><th>Heartbeat UTC</th><th>Reconnects</th><th>Последнее событие (UTC)</th><th>Events</th></tr></thead><tbody>'+data.map(a=>'<tr><td>'+esc(a.node)+'</td><td>'+esc(a.pod)+'</td><td>'+esc(badge(a))+'<div class="muted">'+esc(a.detail)+'</div></td><td>'+esc(a.node_ready===true?'Yes':'No')+'</td><td>'+esc(a.ready===true?'Yes':'No')+'</td><td>'+esc(a.restarts)+'</td><td>'+esc(a.collector?.status||'не настроен')+'</td><td>'+esc(a.collector?.updated_at||'—')+'</td><td>'+esc(a.collector?.reconnects??'—')+'</td><td>'+esc(a.last_seen)+'</td><td>'+esc(a.events)+'</td></tr>').join('')+'</tbody></table>'+(data.length?'':'<div class="empty">Агенты пока не обнаружены</div>');
 $('refresh-agents').addEventListener('click',loadAgents);
 $('sort-description').textContent=data.length+' записей (live + telemetry)';
}

// Metrics are sourced from the detector's loopback /metrics through an authenticated Web API.
function mfmt(n, digits=1){return Number.isFinite(n)?Number(n).toLocaleString('ru-RU',{maximumFractionDigits:digits}):'—'}
function metricRate(samples,key){if(samples.length<2)return null;let latest=samples[samples.length-1];for(let i=samples.length-2;i>=0;i--){const prev=samples[i],seconds=(new Date(latest.at)-new Date(prev.at))/1000;if(seconds>=10){const diff=(latest.values[key]??0)-(prev.values[key]??0);return diff<0?null:diff/seconds}}return null}
function metricPlot(samples,key,asRate=false){let data=[];for(let i=0;i<samples.length;i++){const s=samples[i];const val=asRate && i>0 ? ((s.values[key]??0)-(samples[i-1].values[key]??0))/((new Date(s.at)-new Date(samples[i-1].at))/1000) : s.values[key];if(val!==undefined&&Number.isFinite(val)&&val>=0)data.push(val)}if(!data.length)return '<p class="muted">Недостаточно измерений</p>';const max=Math.max(...data,0.00001);const coordinates=data.map((v,i)=>(8+i*(304/Math.max(data.length-1,1))).toFixed(2)+','+(110-v/max*96).toFixed(2)).join(' ');return '<svg viewBox="0 0 320 120" role="img" aria-label="История показателя"><line x1="8" y1="110" x2="313" y2="110" stroke="#4f6479"/><polyline points="'+coordinates+'" stroke="#5ed2ea" stroke-width="2" fill="none" stroke-linejoin="round"/></svg><div class="muted">Последние '+data.length+' измерений · максимум '+mfmt(max,3)+'</div>'}
let metricsWindow='10m';
async function loadMetrics(){const result=await api('/api/metrics?window='+metricsWindow);const samples=result.samples||[];const current=samples[samples.length-1];if(!current){$('list').innerHTML='<div class="notice">Метрики ещё не получены. Проверьте запуск Detector с -metrics-listen 127.0.0.1:9095 и Web с -detector-metrics.</div>';return}
const v=current.values||{},eps=metricRate(samples,'redo_events_normalized_total'),aps=metricRate(samples,'redo_alerts_total');
const avg=(prefix)=>v[prefix+'_count']>0?v[prefix+'_sum']/v[prefix+'_count']*1000:null;
const tiles=[['Detector',result.available?'Online':'Недоступен'],['Events/sec',eps===null?'—':mfmt(eps,2)],['Alerts/sec',aps===null?'—':mfmt(aps,3)],['Событий обработано',mfmt(v.redo_events_normalized_total,0)],['Алертов',mfmt(v.redo_alerts_total,0)],['Средняя обработка, мс',mfmt(avg('redo_processing_duration_seconds'),2)],['Средняя задержка алерта, мс',mfmt(avg('redo_detection_latency_seconds'),1)],['Go heap, MiB',mfmt((v.redo_process_heap_alloc_bytes||0)/1048576,2)],['CPU time, сек',mfmt(v.redo_process_cpu_seconds_total,1)],['В очереди корреляции',mfmt(v.redo_correlation_pending_events,0)],['Опоздавшие события',mfmt(v.redo_correlation_late_dropped_total,0)],['Досрочные события',mfmt(v.redo_correlation_forced_released_total,0)]];
const charts=[['EPS (нормализованные события)','redo_events_normalized_total',true],['Alerts/sec','redo_alerts_total',true],['Go heap (байты)','redo_process_heap_alloc_bytes',false],['Pending correlation','redo_correlation_pending_events',false]];
$('list').innerHTML='<div class="metric-status">'+(result.available?'🟢 Detector metrics доступны':'🔴 Не удалось связаться с Detector: '+esc(result.error||'устаревшие измерения'))+' · последнее измерение '+esc(current.at)+' <button id="refresh-metrics">Обновить</button> <label>Период: <select id="metric-window"><option value="10m">10 минут</option><option value="1h">1 час</option><option value="24h">24 часа</option></select></label><p class="muted">История метрик сохраняется в ClickHouse (TTL 30 дней), доступные окна: 10 минут, час, 24 часа. Средние значения накопительные за время работы Detector; EPS оценивается по разнице счётчиков. CPU относится только к Detector, heap — не полный RSS.</p></div><div class="metric-grid">'+tiles.map(([n,val])=>'<div class="metric-tile"><span class="muted">'+esc(n)+'</span><div class="metric-value">'+esc(val)+'</div></div>').join('')+'</div><div class="metric-charts">'+charts.map(([name,key,rate])=>'<div class="metric-chart"><h3>'+esc(name)+'</h3>'+metricPlot(samples,key,rate)+'</div>').join('')+'</div>';
$('refresh-metrics').addEventListener('click',loadMetrics);$('metric-window').value=metricsWindow;$('metric-window').addEventListener('change',e=>{metricsWindow=e.target.value;loadMetrics()});$('sort-description').textContent=samples.length+' измерений'}

async function showExceptionPage(){
  $('search-tools').remove();$('workspace').style.display='block';$('workspace').querySelector('section').remove();$('detail').classList.remove('detail-pane');$('detail').innerHTML='<div class="empty">Загрузка выбранного события...</div>';
  const query=new URLSearchParams(location.search),id=query.get('alert_id'),eventID=query.get('event_id'),field=query.get('field');
  try{
    if(!id||!eventID||!field)throw Error('Не указан алерт, событие или поле');
    const data=await api('/api/alerts/'+encodeURIComponent(id));
    const ev=data.events.find(e=>e.event_id===eventID);
    if(!ev)throw Error('Указанное событие не найдено среди связанных');
    const candidate=fieldCandidates(ev).find(([f])=>f===field);
    if(!candidate)throw Error('Поле недоступно для исключения');
    const a=data.alert,value=String(candidate[1]);
    $('detail').innerHTML='<div class="panel-inner"><a href="/alert/'+encodeURIComponent(a.alert_id)+'">← Вернуться к алерту '+esc(a.rule_id)+'</a><h2>Создать исключение</h2><p class="muted">Связанное событие: '+esc(ev.event_type)+' · '+esc(ev.timestamp)+'</p><div class="notice">Исключение действует только на будущие срабатывания указанного правила. Для корреляционных алертов выбранное поле должно присутствовать хотя бы в одном из связанных событий.</div><div class="card"><h3>Точное совпадение</h3><p><b>'+esc(field)+'</b> = '+esc(value)+'</p><p>Правило: '+esc(a.rule_id)+'</p><p>Namespace: '+esc(a.kubernetes?.namespace)+'</p></div><form id="exc-page-form"><label>Pod (рекомендуется оставить ограничение)</label><input name="pod" value="'+esc(a.kubernetes?.pod)+'"><label>Причина исключения</label><textarea name="reason" required placeholder="Обоснование решения аналитика"></textarea><label>Срок действия UTC (RFC3339, до 30 дней)</label><input name="expires" required value="'+new Date(Date.now()+7*86400000).toISOString().replace(/\.\d{3}Z$/,'Z')+'"><p><button type="submit">Создать исключение</button></p><p id="exc-status" role="status"></p></form></div>';
    $('exc-page-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;const payload={rule_id:a.rule_id,namespace:a.kubernetes.namespace,pod:form.elements.pod.value,field,value,reason:form.elements.reason.value,expires_at:form.elements.expires.value};try{await api('/api/exceptions?alert_id='+encodeURIComponent(a.alert_id),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});$('exc-status').textContent='Исключение создано. Проверьте, что активный детектор запущен с -exceptions по тому же пути.'}catch(err){$('exc-status').textContent=err.message}});
  }catch(e){$('detail').innerHTML='<div class="panel-inner error">'+esc(e.message)+'</div>'}
}

document.querySelectorAll('nav button').forEach(btn=>btn.addEventListener('click',()=>{if(pathId||newExceptionPage)location.href='/?tab='+btn.dataset.tab;else {history.replaceState(null,'','/?tab='+btn.dataset.tab);exceptionRuleFilter='';setTab(btn.dataset.tab)}}));$('search-btn').addEventListener('click',load);$('query').addEventListener('keydown',e=>{if(e.key==='Enter')load()});$('namespace').addEventListener('keydown',e=>{if(e.key==='Enter')load()});
if(newExceptionPage){showExceptionPage()}else if(pathId){document.querySelector('main').classList.add('detail-page');$('search-tools').remove();$('workspace').style.display='block';$('workspace').querySelector('section').remove();$('detail').classList.remove('detail-pane');$('detail').innerHTML='<div class="empty">Загрузка алерта...</div>';showAlert(pathId)}else{const requested=new URLSearchParams(location.search).get('tab');exceptionRuleFilter=new URLSearchParams(location.search).get('rule')||'';setTab(['alerts','events','exceptions','agents','metrics'].includes(requested)?requested:'alerts')}
setInterval(()=>{if(!pathId&&!newExceptionPage&&tab!=='exceptions'&&!activeId)load()},15000);
</script></body></html>`
